        valueInputs.remove(node.id);
        editingInputs.remove(node.id);
        dateInputs.remove(node.id);
        mediaInputs.remove(node.id);
        fitInputs.remove(node.id);
        navigateActions.remove(node.id);
        proxyViews.remove(node.id);
